<?php
require __DIR__.'/config.php';$me=require_auth();$cid=(int)$me['customer_id'];$errors=[];$v=$_POST;$types=[];$branches=[];
try{$types=db()->query("SELECT account_type_id,type_name,minimum_balance,single_per_customer FROM account_types WHERE LOWER(type_name) LIKE '%savings%' OR LOWER(type_name) LIKE '%current%' ORDER BY type_name")->fetchAll();$branches=db()->query("SELECT branch_id,branch_name FROM branches WHERE status='active' ORDER BY branch_name")->fetchAll();}catch(Throwable $x){$errors[]='Account applications are temporarily unavailable.';}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$typeId=filter_var($_POST['account_type_id']??null,FILTER_VALIDATE_INT);$branchId=filter_var($_POST['branch_id']??null,FILTER_VALIDATE_INT);$holderType=(string)($_POST['holder_type']??'single');$mode=(string)($_POST['operating_mode']??'either_or_survivor');$title=trim((string)($_POST['account_title']??''));$jointEmail=strtolower(trim((string)($_POST['joint_email']??'')));$jointPhone=trim((string)($_POST['joint_phone']??''));
    if(!$typeId||!in_array((int)$typeId,array_map(fn($t)=>(int)$t['account_type_id'],$types),true))$errors[]='Choose a savings or current account type.';
    if(!$branchId||!in_array((int)$branchId,array_map(fn($b)=>(int)$b['branch_id'],$branches),true))$errors[]='Choose an active branch.';
    if(!in_array($holderType,['single','joint'],true))$errors[]='Choose single or joint ownership.';
    if($holderType==='joint'&&(!in_array($mode,['either_or_survivor','jointly'],true)||!filter_var($jointEmail,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9+() -]{7,20}$/',$jointPhone)))$errors[]='Enter the joint holder’s email and phone, and choose how the account may be operated.';
    if($holderType==='joint'&&($_POST['joint_consent']??'')!=='yes')$errors[]='Confirm that the joint holder has agreed to be included.';
    if(strlen($title)>150)$errors[]='Account title must be 150 characters or fewer.';
    if(!$errors){$pdo=db();try{$pdo->beginTransaction();$customer=$pdo->prepare("SELECT full_name,status FROM customers WHERE customer_id=?");$customer->execute([$cid]);$primary=$customer->fetch();if(!$primary||$primary['status']!=='active')throw new RuntimeException();$type=$pdo->prepare("SELECT type_name,minimum_balance,single_per_customer FROM account_types WHERE account_type_id=? AND (LOWER(type_name) LIKE '%savings%' OR LOWER(type_name) LIKE '%current%')");$type->execute([(int)$typeId]);$accountType=$type->fetch();if(!$accountType)throw new RuntimeException();$branch=$pdo->prepare("SELECT branch_id FROM branches WHERE branch_id=? AND status='active'");$branch->execute([(int)$branchId]);if(!$branch->fetchColumn())throw new RuntimeException();if((int)$accountType['single_per_customer']===1){$exists=$pdo->prepare('SELECT 1 FROM account_holders h JOIN accounts a ON a.account_id=h.account_id WHERE h.customer_id=? AND a.account_type_id=? LIMIT 1');$exists->execute([$cid,(int)$typeId]);if($exists->fetchColumn())throw new RuntimeException();}
        $joint=null;if($holderType==='joint'){$other=$pdo->prepare("SELECT customer_id,full_name FROM customers WHERE LOWER(email)=LOWER(?) AND phone=? AND status='active' AND customer_id<>? LIMIT 1");$other->execute([$jointEmail,$jointPhone,$cid]);$joint=$other->fetch();if(!$joint)throw new RuntimeException();}
        $accountTitle=$title?:$primary['full_name'];$number=null;$exists=$pdo->prepare('SELECT 1 FROM accounts WHERE account_number=?');for($i=0;$i<20;$i++){$candidate='BE'.str_pad((string)$branchId,3,'0',STR_PAD_LEFT).random_int(1000000000,9999999999);$exists->execute([$candidate]);if(!$exists->fetchColumn()){$number=$candidate;break;}}if($number===null)throw new RuntimeException();$add=$pdo->prepare("INSERT INTO accounts (account_number,account_title,account_type_id,branch_id,balance,status,opening_date) VALUES (?,?,?,?,0,'pending',CURDATE())");$add->execute([$number,$accountTitle,(int)$typeId,(int)$branchId]);$accountId=(int)$pdo->lastInsertId();$holders=$pdo->prepare('INSERT INTO account_holders (account_id,customer_id,holder_role,operating_mode) VALUES (?,?,?,?)');$holders->execute([$accountId,$cid,'primary',$holderType==='joint'?$mode:'single']);if($joint)$holders->execute([$accountId,(int)$joint['customer_id'],'joint',$mode]);$notify=$pdo->prepare("INSERT INTO notifications (user_id,type,message) VALUES (?,'account_request',?)");$notify->execute([$me['id'],'Account application #'.$accountId.' received and pending staff review.']);notify_account_application($pdo,$cid,$accountId,$joint ? (int)$joint["customer_id"] : null);$pdo->commit();flash('Account application submitted. It will remain pending until staff verify the application and KYC details.');go('account.php?id='.$accountId);
    }catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$errors[]='We could not submit the account application. Check the account type, branch, and joint holder details, then try again.';}}
}
render_start('Open another account');?><section class="page-heading"><div class="eyebrow dark">Grow with BankEase</div><h1>Open another account</h1><p>Apply for an additional savings or current account. Every new account remains pending until staff review.</p></section><?php if($errors):?><div class="notice error" role="alert"><ul><?php foreach(array_unique($errors) as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="application-form"><?=csrf()?><div class="form-grid"><div class="field"><label for="account_type_id">Account type</label><select id="account_type_id" name="account_type_id" required><option value="">Choose account type</option><?php foreach($types as $t):?><option value="<?=$t['account_type_id']?>" <?=((string)($v['account_type_id']??''))===(string)$t['account_type_id']?'selected':''?>><?=e($t['type_name'])?> · minimum BDT <?=e(number_format((float)$t['minimum_balance'],2))?></option><?php endforeach;?></select></div><div class="field"><label for="branch_id">Branch</label><select id="branch_id" name="branch_id" required><option value="">Choose branch</option><?php foreach($branches as $b):?><option value="<?=$b['branch_id']?>" <?=((string)($v['branch_id']??''))===(string)$b['branch_id']?'selected':''?>><?=e($b['branch_name'])?></option><?php endforeach;?></select></div><div class="field"><label for="holder_type">Ownership</label><select id="holder_type" name="holder_type"><option value="single">Individual account</option><option value="joint" <?=($v['holder_type']??'')==='joint'?'selected':''?>>Joint account</option></select></div><div class="field"><label for="account_title">Account title <span class="muted">(optional)</span></label><input id="account_title" name="account_title" maxlength="150" value="<?=e($v['account_title']??'')?>"></div><div class="joint-fields" hidden><h2>Joint holder</h2><p class="muted">The other holder must already have an active BankEase customer profile. Staff will verify both holders before the account is activated.</p><div class="form-grid"><div class="field"><label for="joint_email">Joint holder email</label><input id="joint_email" name="joint_email" type="email" autocomplete="off" value="<?=e($v['joint_email']??'')?>" disabled></div><div class="field"><label for="joint_phone">Joint holder phone</label><input id="joint_phone" name="joint_phone" type="tel" autocomplete="off" value="<?=e($v['joint_phone']??'')?>" disabled></div><div class="field"><label for="operating_mode">Operating instruction</label><select id="operating_mode" name="operating_mode" disabled><option value="either_or_survivor">Either holder may operate</option><option value="jointly" <?=($v['operating_mode']??'')==='jointly'?'selected':''?>>Both holders operate jointly</option></select></div><div class="field consent"><label><input type="checkbox" name="joint_consent" value="yes" <?=($v['joint_consent']??'')==='yes'?'checked':''?> disabled> I confirm the other holder has agreed to this application.</label></div></div></div><div class="full"><button class="button navy" type="submit">Submit account application</button></div></div></form><?php render_end();?>
